enum : unsigned {
  EF_SBF_V2 = 0x20,
};

namespace {

class SBFAsmBackend : public MCAsmBackend {
public:
  SBFAsmBackend(endianness Endian, const MCSubtargetInfo &STI)
      : MCAsmBackend(Endian),
        isSBFv2(STI.getCPU() == "sbfv2"),
        isSolana(STI.hasFeature(SBF::FeatureSolana) ||
                 STI.getTargetTriple().getArch() == Triple::sbf),
        relocAbs64(STI.hasFeature(SBF::FeatureRelocAbs64)) {}
  ~SBFAsmBackend() override = default;

std::unique_ptr<MCObjectTargetWriter>
SBFAsmBackend::createObjectTargetWriter() const {
  return createSBFELFObjectWriter(0, isSolana, relocAbs64, isSBFv2);
}

SBFELFObjectWriter::SBFELFObjectWriter(uint8_t OSABI, bool isSolana,
                                       bool relocAbs64, bool isSBFv2)
  : MCELFObjectTargetWriter(/*Is64Bit*/ true, OSABI,
                            isSBFv2 ? ELF::EM_SBF : ELF::EM_BPF,
                            /*HasRelocationAddend*/ false),
      isSolana(isSolana), relocAbs64(relocAbs64) {}

static MCStreamer *createSBFMCStreamer(const Triple &T, MCContext &Ctx,
                                       std::unique_ptr<MCAsmBackend> &&MAB,
                                       std::unique_ptr<MCObjectWriter> &&OW,
                                       std::unique_ptr<MCCodeEmitter> &&Emitter,
                                       bool RelaxAll) {
  MCELFStreamer *S =
      new MCELFStreamer(Ctx, std::move(MAB), std::move(OW), std::move(Emitter));
  if (RelaxAll)
    S->getAssembler().setRelaxAll(true);
  const MCSubtargetInfo *STI = Ctx.getSubtargetInfo();
  if (STI->getCPU() == "sbfv2") {
    S->getAssembler().setELFHeaderEFlags(llvm::ELF::EF_SBF_V2);
  }
  return S;
}

static uint32_t getEFlags(InputFile *file) {
  if (config->ekind == ELF64BEKind)
    return cast<ObjFile<ELF64BE>>(file)->getObj().getHeader().e_flags;
  return cast<ObjFile<ELF64LE>>(file)->getObj().getHeader().e_flags;
}

uint32_t SBF::calcEFlags() const {
  uint32_t ret = 0;

  // Ensure that all the object files were compiled with the same flags, as
  // different flags indicate different ABIs.
  for (InputFile *f : ctx.objectFiles) {
    uint32_t flags = getEFlags(f);
    if (ret == 0) {
      ret = flags;
    } else if (ret != flags) {
      error("can not link object files with incompatible flags");
    }
  }

  return ret;
}

// SBF specific e_flags
enum : unsigned {
  EF_SBF_V0 = 0x00,
  EF_SBF_V1 = 0x01,
  EF_SBF_V2 = 0x02,
  EF_SBF_V3 = 0x03,
};

SBFELFObjectWriter::SBFELFObjectWriter(uint8_t OSABI, bool relocAbs64)
  : MCELFObjectTargetWriter(/*Is64Bit*/ true, OSABI,ELF::EM_SBF,
                            /*HasRelocationAddend*/ false),
      relocAbs64(relocAbs64) {}

StringRef CPU = STI->getCPU();
unsigned EFlag = llvm::ELF::EF_SBF_V0;
if (CPU == "v1") {
  EFlag = llvm::ELF::EF_SBF_V1;
} else if (CPU == "v2") {
  EFlag = llvm::ELF::EF_SBF_V2;
} else if (CPU == "v3") {
  EFlag = llvm::ELF::EF_SBF_V3;
}
S->getAssembler().setELFHeaderEFlags(EFlag);

return S;

static uint32_t getEFlags(InputFile *file) {
